<?php

declare(strict_types=1);

namespace App\Domains\Azkar\Services;

/**
 * Decides which rows of the reviewed Quran reference map an import may use (ADR 0031 §4, §11).
 *
 * - `reviewed`: set by the developer. Accepted everywhere.
 * - `candidate`: generated by azkar:quran-map-candidates. Accepted outside production, listed as a warning.
 *   Production blocks it.
 * - `unmatched`: no confident match. Always blocks the entry.
 *
 * A row holds one span's references: [surah, verse_from, verse_to|null, 'status', 'evidence', 'check'?, 'ranges'?].
 * `ranges` is present only for a span that runs across surah boundaries, and lists every range in order.
 */
final class QuranReferencePolicy
{
    public const string REVIEWED = 'reviewed';

    public const string CANDIDATE = 'candidate';

    public const string UNMATCHED = 'unmatched';

    public const string DECISION_ACCEPT = 'accept';

    public const string DECISION_WARN_CANDIDATE = 'warn_candidate';

    public const string DECISION_BLOCK = 'block';

    public const string DECISION_INVALID = 'invalid';

    /**
     * Parses one map row. Returns null when the row is malformed. An unmatched row may hold null references, because
     * it carries no range to use.
     *
     * @return array{surah: int|null, from: int|null, to: int|null, status: string, evidence: string|null, ranges: list<array{0: int, 1: int, 2: int|null}>}|null
     */
    public function parse(mixed $row): ?array
    {
        if (! is_array($row) || ! array_key_exists(0, $row) || ! array_key_exists(1, $row) || ! array_key_exists(2, $row)) {
            return null;
        }

        $status = $row['status'] ?? null;
        $evidence = $row['evidence'] ?? null;

        if (! is_string($status) || ($evidence !== null && ! is_string($evidence))) {
            return null;
        }

        [$surah, $from, $to] = [$row[0], $row[1], $row[2]];

        if ($status === self::UNMATCHED && $surah === null && $from === null && $to === null) {
            return ['surah' => null, 'from' => null, 'to' => null, 'status' => $status, 'evidence' => $evidence, 'ranges' => []];
        }

        if (! is_int($surah) || $surah < 1 || ! is_int($from) || $from < 1) {
            return null;
        }

        if ($to !== null && (! is_int($to) || $to < $from)) {
            return null;
        }

        $ranges = [[$surah, $from, $to]];

        if (array_key_exists('ranges', $row)) {
            $ranges = $this->parseRanges($row['ranges']);

            if ($ranges === null || $ranges[0] !== [$surah, $from, $to]) {
                return null;
            }
        }

        return ['surah' => $surah, 'from' => $from, 'to' => $to, 'status' => $status, 'evidence' => $evidence, 'ranges' => $ranges];
    }

    /**
     * @return list<array{0: int, 1: int, 2: int|null}>|null
     */
    private function parseRanges(mixed $value): ?array
    {
        if (! is_array($value) || ! array_is_list($value) || $value === []) {
            return null;
        }

        $ranges = [];

        foreach ($value as $range) {
            if (! is_array($range) || ! array_is_list($range) || count($range) !== 3) {
                return null;
            }

            [$surah, $from, $to] = $range;

            if (! is_int($surah) || $surah < 1 || ! is_int($from) || $from < 1 || ($to !== null && (! is_int($to) || $to < $from))) {
                return null;
            }

            $ranges[] = [$surah, $from, $to];
        }

        return $ranges;
    }

    /**
     * @param  array{status: string}  $row  A parsed row
     */
    public function decide(array $row): string
    {
        return match ($row['status']) {
            self::REVIEWED => self::DECISION_ACCEPT,
            self::CANDIDATE => $this->candidatesAccepted() ? self::DECISION_WARN_CANDIDATE : self::DECISION_BLOCK,
            self::UNMATCHED => self::DECISION_BLOCK,
            default => self::DECISION_INVALID,
        };
    }

    /**
     * Production imports accept only rows the developer has reviewed (ADR 0031 §11).
     */
    public function candidatesAccepted(): bool
    {
        return ! app()->isProduction();
    }
}
